const item = $input.first().json;
const { transcript, agent_system_prompt, extraction_config, metadata } = item;
const errors = [];

if (!transcript || typeof transcript !== 'string' || transcript.trim().length === 0) {
  errors.push('transcript is required and must be a non-empty string');
}
if (!agent_system_prompt || typeof agent_system_prompt !== 'string') {
  errors.push('agent_system_prompt is required');
}
if (!extraction_config || !Array.isArray(extraction_config.categories) || extraction_config.categories.length === 0) {
  errors.push('extraction_config.categories must be a non-empty array');
} else {
  for (const cat of extraction_config.categories) {
    if (!cat.category_id || !Array.isArray(cat.fields) || cat.fields.length === 0) {
      errors.push(`Category '${cat.category_id || 'unknown'}' must have category_id and non-empty fields`);
    }
  }
}

const extraction_id = 'ext_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);

if (errors.length > 0) {
  return [{ json: { valid: false, extraction_id, errors } }];
}

return [{ json: { valid: true, extraction_id, transcript, agent_system_prompt, extraction_config, metadata: metadata || {} } }];

const { extraction_id, errors } = $input.first().json;
return [{ json: {
  extraction_id,
  timestamp: new Date().toISOString(),
  model: 'gemini-3-pro',
  categories_processed: 0,
  fields: [],
  errors: errors.map(e => ({ type: 'validation', message: e }))
} }];

const { extraction_id, transcript, agent_system_prompt, extraction_config, metadata, google_api_key } = $input.first().json;
const global_context = extraction_config.global_context || {};
return extraction_config.categories.map(category => ({
  json: { extraction_id, transcript, agent_system_prompt, category, global_context, google_api_key }
}));

const { category, transcript, agent_system_prompt, global_context, google_api_key } = $input.item.json;

function inferStrictness(field) {
  if (field.strictness) return field.strictness;
  if (['boolean','phone','email'].includes(field.type)) return 'high';
  if (field.validation && field.validation.pattern) return 'high';
  if (field.type === 'enum' && field.values && field.values.length <= 5) return 'high';
  if (field.type === 'enum') return 'medium';
  if (field.type === 'string' && field.required) return 'medium';
  if (/summary|notes|description/i.test(field.field_id)) return 'low';
  if (field.type === 'string' && !field.required) return 'low';
  return 'medium';
}

const compA = '== TRANSCRIPT ==\n' + transcript;
const compB = '== CONTEXT ==\n' + agent_system_prompt;

const schema = {};
for (const f of category.fields) {
  if (f.type === 'boolean') schema[f.field_id] = 'boolean | null';
  else if (f.type === 'enum') schema[f.field_id] = (f.values || []).join(' | ');
  else if (f.type === 'number') schema[f.field_id] = 'number | null';
  else schema[f.field_id] = 'string | null';
}
const compC = '== RESPONSE SCHEMA ==\nReturn a JSON object with exactly these keys:\n' + JSON.stringify(schema, null, 2) + '\n\nAlso include a \"_rationale\" object with the same keys, where each value explains your reasoning.\nAlso include a \"_confidence\" object with the same keys, where each value is a number 0.0-1.0.';

const fieldLines = category.fields.map(function(f) {
  var prompt = f.prompt || 'Extract the ' + f.field_id + ' from the transcript.';
  var s = inferStrictness(f);
  var line = '- **' + f.field_id + '** (' + f.type + '): ' + prompt;
  if (f.type === 'enum' && f.values) line += '\n  Allowed values: ' + f.values.join(', ');
  if (f.required) line += '\n  Required. Default: ' + JSON.stringify(f.default_value !== undefined ? f.default_value : null);
  line += '\n  Strictness: ' + s;
  return line;
}).join('\n\n');
const compD = '== FIELD INSTRUCTIONS ==\n' + fieldLines;

const rules = category.context_rules || {};
var compE = '== EXTRACTION RULES ==\nDefault strictness: ' + (rules.default_strictness || 'medium') + '\nRationale required: ' + (rules.require_rationale !== undefined ? rules.require_rationale : true) + '\nNull behavior: ' + (rules.null_behavior || 'return_null_with_rationale') + '\n\nStrictness guide:\n- HIGH: Exact match only. Return null if ambiguous. Enums must match exactly.\n- MEDIUM: Best-effort extraction. Use \"unknown\" if unsure.\n- LOW: Flexible summarization. Creative interpretation OK.\n\nConfidence scoring: 0.0 = pure guess, 0.5 = some evidence, 0.8 = strong evidence, 1.0 = explicitly stated.\nIf a field is not mentioned in the transcript at all, return null with confidence 0.0.';
if (global_context && global_context.agent_identity) compE += '\nAgent identity: ' + global_context.agent_identity;
if (global_context && global_context.business_domain) compE += '\nBusiness domain: ' + global_context.business_domain;

const fullPrompt = 'You are a structured data extraction engine. Extract fields from the transcript below.\n\n' + compA + '\n\n' + compB + '\n\n' + compC + '\n\n' + compD + '\n\n' + compE;

return { json: { prompt: fullPrompt, category_id: category.category_id, fields: category.fields, context_rules: category.context_rules || {}, google_api_key: google_api_key } };

const input = $input.item.json;
const category_id = $('Build 5-Component Prompt').item.json.category_id;
const fields = $('Build 5-Component Prompt').item.json.fields;

let parsed;
try {
  const body = input.body || input;
  const text = body && body.candidates && body.candidates[0] && body.candidates[0].content && body.candidates[0].content.parts && body.candidates[0].content.parts[0] && body.candidates[0].content.parts[0].text;
  if (!text) throw new Error('No text in Gemini response');
  parsed = JSON.parse(text);
} catch (e) {
  return { json: {
    category_id: category_id,
    envelopes: [],
    error: { type: 'parse_error', category: category_id, message: 'Failed to parse Gemini response: ' + e.message }
  } };
}

const E164 = /^\+[1-9]\d{1,14}$/;
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function repair(field, raw) {
  if (raw === null || raw === undefined) return null;
  if (field.type === 'boolean') {
    if (typeof raw === 'boolean') return raw;
    if (typeof raw === 'string') {
      if (raw.toLowerCase() === 'true') return true;
      if (raw.toLowerCase() === 'false') return false;
    }
    return null;
  }
  if (field.type === 'enum' && field.values) {
    const str = String(raw).trim();
    const exact = field.values.find(function(v) { return v === str; });
    if (exact) return exact;
    const ci = field.values.find(function(v) { return v.toLowerCase() === str.toLowerCase(); });
    if (ci) return ci;
    return str;
  }
  if (typeof raw === 'string') return raw.trim();
  return raw;
}

function validate(field, value) {
  if (value === null || value === undefined) return !field.required;
  switch (field.type) {
    case 'boolean': return typeof value === 'boolean';
    case 'phone': return typeof value === 'string' && E164.test(value);
    case 'email': return typeof value === 'string' && EMAIL.test(value);
    case 'enum': return typeof value === 'string' && (!field.values || field.values.includes(value));
    case 'number': return typeof value === 'number' && !isNaN(value);
    case 'string': return typeof value === 'string' && value.length > 0;
    default: return true;
  }
}

function inferStrictness(field) {
  if (field.strictness) return field.strictness;
  if (['boolean','phone','email'].includes(field.type)) return 'high';
  if (field.type === 'enum' && field.values && field.values.length <= 5) return 'high';
  if (field.type === 'enum') return 'medium';
  if (field.type === 'string' && field.required) return 'medium';
  if (/summary|notes|description/i.test(field.field_id)) return 'low';
  if (field.type === 'string' && !field.required) return 'low';
  return 'medium';
}

const rationales = parsed._rationale || {};
const confidences = parsed._confidence || {};
const envelopes = [];

for (const field of fields) {
  const raw = parsed[field.field_id];
  const value = repair(field, raw);
  const valid = validate(field, value);
  const finalValue = (!valid && field.required && field.default_value !== undefined) ? field.default_value : value;

  envelopes.push({
    category: category_id,
    field_id: field.field_id,
    value: finalValue,
    rationale: rationales[field.field_id] || null,
    confidence: typeof confidences[field.field_id] === 'number' ? confidences[field.field_id] : 0,
    strictness_applied: inferStrictness(field),
    validation_passed: valid || (finalValue !== value)
  });
}

return { json: { category_id: category_id, envelopes: envelopes, error: null } };

const items = $input.all();
let extraction_id = 'ext_unknown';
try { extraction_id = $('Split Categories').first().json.extraction_id; } catch(e) {}

const allEnvelopes = [];
const allErrors = [];
let categoriesProcessed = 0;

for (const item of items) {
  const data = item.json;
  if (data.envelopes && Array.isArray(data.envelopes)) {
    allEnvelopes.push(...data.envelopes);
    categoriesProcessed++;
  }
  if (data.error) {
    allErrors.push(data.error);
  }
}

const seen = new Set();
const deduped = allEnvelopes.filter(function(e) {
  const key = e.category + ':' + e.field_id;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

deduped.sort(function(a, b) { return a.category.localeCompare(b.category) || a.field_id.localeCompare(b.field_id); });

return [{ json: {
  extraction_id: extraction_id,
  timestamp: new Date().toISOString(),
  model: 'gemini-3-pro',
  categories_processed: categoriesProcessed,
  fields: deduped,
  errors: allErrors
} }];
